#!/usr/bin/env bash
# Sauvegarde 1fichier ★ BLONDIN EDITION ★ — Installateur UNIQUE hors ligne
# Batocera 44 / v3.4.4 COMPLETE AUTONOME (Batocera + Mobile)
# Installation complete autonome hors ligne, aucune version 1fichier precedente requise.
# Le lancement graphique purge DISPLAY, WAYLAND_DISPLAY et WLR_BACKENDS.
# Aucun redemarrage systeme si une etape echoue ; garde extinction strict conserve.
# Aucun transfert de sauvegarde n'est declenche par l'installation.
set -Eeuo pipefail

if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
  echo '[ERREUR] Installer en root par SSH sur Batocera 44.' >&2
  exit 1
fi
for cmd in bash python3 flock; do
  command -v "$cmd" >/dev/null 2>&1 || { echo "[ERREUR] Commande manquante : $cmd" >&2; exit 1; }
done
# Sur Batocera reel, le reboot est requis par cet installateur.
# Les tests BLONDIN_TEST_ROOT ne doivent jamais redemarrer l'hote de test.
if [[ -z "${BLONDIN_TEST_ROOT:-}" ]]; then
  command -v reboot >/dev/null 2>&1 || {
    echo '[ERREUR] reboot indisponible : installation non demarree.' >&2; exit 1;
  }
fi
SYSROOT="${BLONDIN_TEST_ROOT:-/userdata}"
BASE="$SYSROOT/system/1fichier-blondin"
TRIGGER="$SYSROOT/system/configs/emulationstation/scripts/screensaver-start/shutdown-trigger.sh"
CANCEL="$SYSROOT/system/configs/emulationstation/scripts/screensaver-stop/shutdown-cancel.sh"
PORT="$SYSROOT/roms/ports/Sauvegarde 1fichier - BLONDIN EDITION.sh"
WEB="$BASE/mobile"
SVC="$SYSROOT/system/services/Sauvegarde1fichierMobile"

# v3.4.4 COMPLETE : le service Extinction V3 est facultatif.
# S'il existe, sa protection historique reste inchangee ; sinon aucun fichier
# d'extinction n'est cree ou modifie.
SHUTDOWN_V3_PRESENT=0
if [[ -f "$TRIGGER" && -f "$CANCEL" ]]; then
  SHUTDOWN_V3_PRESENT=1
elif [[ -e "$TRIGGER" || -e "$CANCEL" || -L "$TRIGGER" || -L "$CANCEL" ]]; then
  echo '[ERREUR] Extinction V3 partiellement installee : aucun changement.' >&2
  exit 1
else
  echo '[INFO] Extinction automatique V3 absente : installation 1fichier autonome sans ce module.'
fi
if [[ -L "$TRIGGER" || -L "$CANCEL" || -L "$BASE" || -L "$BASE/transfert.lock" ]]; then
  echo '[ERREUR] Lien symbolique inattendu dans un fichier sensible.' >&2
  exit 1
fi
if [[ "$SHUTDOWN_V3_PRESENT" == 1 ]] && ! bash -n "$TRIGGER"; then
  echo '[ERREUR] Script extinction existant invalide. Installation abandonnee.' >&2
  exit 1
fi
# Verrou verifie AVANT modification. Le serveur Web d'une ancienne I2 peut
# avoir herite accidentellement du FD exclusif. Ne pas casser un vrai transfert.
WAS_WEB_RUNNING=0
WEB_STOPPED_FOR_UPGRADE=0
# Uniquement restaurer ES si la session etait active AVANT notre intervention.
WAS_ES_RUNNING=0
if [[ -z "${BLONDIN_TEST_ROOT:-}" ]] && { pgrep -x labwc >/dev/null 2>&1 || pgrep -x emulationstation >/dev/null 2>&1; }; then
  WAS_ES_RUNNING=1
fi
start_es_clean_outer() {
  local logfile="$SYSROOT/system/logs/sauvegarde-1fichier-relance-es-v3.0.log"
  mkdir -p -- "$(dirname "$logfile")"
  echo '[INFO] Recuperation EmulationStation : environnement Wayland nettoye.'
  nohup env -u DISPLAY -u WAYLAND_DISPLAY -u WLR_BACKENDS \
    /etc/init.d/S31emulationstation start >> "$logfile" 2>&1 < /dev/null &
  local starter=$!
  wait "$starter" || true
  local i stable=0
  for ((i=0;i<25;i++)); do
    if pgrep -x labwc >/dev/null 2>&1; then
      stable=$((stable+1))
      if (( stable>=3 )); then return 0; fi
    else
      stable=0
    fi
    sleep 1
  done
  echo "[ERREUR] Labwc non actif apres relance. Journal : $logfile" >&2
  return 1
}
recover_es_on_failure() {
  [[ -n "${BLONDIN_TEST_ROOT:-}" || "$WAS_ES_RUNNING" != 1 ]] && return 0
  if pgrep -x labwc >/dev/null 2>&1; then return 0; fi
  echo '[ATTENTION] Installation echouee et session graphique absente ; recuperation automatique.' >&2
  start_es_clean_outer || true
}
if [[ -z "${BLONDIN_TEST_ROOT:-}" && -f "$SVC" ]]; then
  if bash "$SVC" status 2>/dev/null | grep -q 'active'; then
    WAS_WEB_RUNNING=1
  fi
fi
web_restore_on_failure() {
  local rc=${1:-1}
  if [[ "$rc" -ne 0 && "$WEB_STOPPED_FOR_UPGRADE" == 1 && "$WAS_WEB_RUNNING" == 1 && -f "$SVC" ]]; then
    echo '[INFO] Echec installation : remise en route de l interface mobile precedente.' >&2
    bash "$SVC" start >/dev/null 2>&1 || true
  fi
}
lock_available() {
  [[ ! -d "$BASE" || ! -e "$BASE/transfert.lock" ]] && return 0
  (exec 8>>"$BASE/transfert.lock"; flock -n -x 8)
}
# Check active worker PID + UUID, not just a stale JSON file.
verified_worker_active() {
  python3 - "$BASE" <<'PY_CHECK_WORKER'
import json,re,sys
from pathlib import Path
base=Path(sys.argv[1]); state=base/'transfert-actif.json'; app=base/'app.py'
try:
 data=json.loads(state.read_text());pid=data.get('pid');job=data.get('job')
 if not isinstance(pid,int) or pid<2 or not isinstance(job,str) or not re.fullmatch(r'[0-9a-f]{16}',job):raise ValueError()
 cmd=Path('/proc/%d/cmdline'%pid).read_bytes().rstrip(b'\0').split(b'\0')
 if len(cmd)<6 or cmd[1]!=b'-u' or Path(cmd[2].decode()).resolve()!=app.resolve():raise ValueError()
 if cmd[3]==b'--worker' and len(cmd)>6 and cmd[6].decode()==job:sys.exit(0)
 if cmd[3]==b'--repair-worker' and cmd[5].decode()==job:sys.exit(0)
 if cmd[3]==b'--media-retry-worker' and len(cmd)==8 and cmd[5].decode()==job:sys.exit(0)
except (OSError,ValueError,UnicodeError,TypeError,KeyError,IndexError):pass
sys.exit(1)
PY_CHECK_WORKER
}
if ! lock_available; then
  if verified_worker_active; then
    echo '[ERREUR] Sauvegarde, renvoi ZIP, verification ou reparation effectivement active : aucune mise a jour.' >&2
    exit 1
  fi
  if [[ "$WAS_WEB_RUNNING" == 1 ]]; then
    echo '[INFO] Verrou occupe sans worker reconnu : arret temporaire du service Web pour diagnostic.'
    bash "$SVC" stop >/dev/null 2>&1 || true
    WEB_STOPPED_FOR_UPGRADE=1
  fi
  for _i in 1 2 3 4 5 6; do
    lock_available && break
    sleep 0.5
  done
  if ! lock_available; then
    echo '[ERREUR] Verrou toujours occupe : operation inconnue, mise a jour refusee.' >&2
    echo '[INFO] Ne pas supprimer transfert.lock. Examiner les processus actifs.' >&2
    exit 1
  fi
  echo '[OK] Verrou libere : le serveur Web precedent conservait probablement un descripteur.'
fi
# Arreter uniquement le serveur Web, pas un worker detache.
if [[ "$WAS_WEB_RUNNING" == 1 && "$WEB_STOPPED_FOR_UPGRADE" != 1 ]]; then
  bash "$SVC" stop >/dev/null 2>&1 || true
  WEB_STOPPED_FOR_UPGRADE=1
fi
# Tous les modules sont installes avant de lancer un serveur Web.
export BLONDIN_DEFER_WEB_START=1

WORK=$(mktemp -d "${TMPDIR:-/tmp}/blondin-v300.XXXXXXXX") || exit 1
chmod 700 "$WORK"
cleanup() { rm -rf -- "$WORK"; }
finish_install() {
  local rc=$?
  trap - EXIT
  cleanup
  if (( rc != 0 )); then
    recover_es_on_failure
    web_restore_on_failure "$rc"
    echo '[INFO] Aucun redemarrage complet de Batocera apres cet echec.' >&2
  fi
  exit "$rc"
}
trap finish_install EXIT

python3 - "$0" "$WORK" <<'PY_UNPACK'
import base64,hashlib,io,os,sys,tarfile
from pathlib import Path
path=Path(sys.argv[1]); out=Path(sys.argv[2])
raw=path.read_bytes()
start=b'# __BLONDIN_BUNDLE_BEGIN__\n'
end=b'\n# __BLONDIN_BUNDLE_END__'
if raw.count(start)!=1 or raw.count(end)!=1:raise SystemExit('[ERREUR] Archive embarquee absente.')
encoded=raw.split(start,1)[1].split(end,1)[0]
try:blob=base64.b64decode(encoded,validate=False)
except Exception as exc:raise SystemExit('[ERREUR] Archive illisible : '+str(exc))
if hashlib.sha256(blob).hexdigest()!='6bfca85c84a4682532c066c4f29cf6292e7c3b0c29398ef150c67ca4023528c3':
    raise SystemExit('[ERREUR] Archive integree incorrecte ; installation annulee.')
names={'01-moteur.sh','02-garde-extinction.sh','03-mobile.sh','04-correctifs-R1-M1.2.sh','05-compte-R2-M1.3.sh','06-journaux-v2.1.sh','07-web-v2.2.sh','08-verification-manuelle-v2.2.sh'}
with tarfile.open(fileobj=io.BytesIO(blob),mode='r:gz') as tf:
    members=tf.getmembers()
    if len(members)!=len(names) or {m.name for m in members}!=names or any(not m.isfile() for m in members):
        raise SystemExit('[ERREUR] Contenu du paquet inattendu.')
    for m in members:
        b=tf.extractfile(m).read()
        p=out/m.name
        p.write_bytes(b)
        p.chmod(0o700)
print('[OK] 8 modules verifies et prepares pour l installation hors ligne.')
PY_UNPACK
# Nouveau moteur + interfaces COMPLETS, embarques directement dans ce fichier.
python3 - "$0" "$WORK" <<'PY_UNPACK_V300'
import base64,hashlib,io,sys,tarfile
from pathlib import Path
source=Path(sys.argv[1]).read_bytes()
start=b'# __BLONDIN_V300_BUNDLE_BEGIN__\n'
end=b'\n# __BLONDIN_V300_BUNDLE_END__'
if source.count(start)!=1 or source.count(end)!=1:
    raise SystemExit('[ERREUR] Archive v3.0 absente, aucune installation.')
encoded=source.split(start,1)[1].split(end,1)[0]
archive=base64.b64decode(encoded,validate=False)
if hashlib.sha256(archive).hexdigest()!='f8507a13fcf94359f2a3f0b03e08c643f91657245ec0580fbc9c8ef52521bfdc':
    raise SystemExit('[ERREUR] Signature de l archive v3.0 incorrecte.')
expected={'app.py','media_v23.py','mobile/app.js','mobile/index.html','mobile/mobile_web.py'}
with tarfile.open(fileobj=io.BytesIO(archive),mode='r:gz') as tar:
    members=tar.getmembers()
    if len(members)!=len(expected) or {x.name for x in members}!=expected or any(not x.isfile() for x in members):
        raise SystemExit('[ERREUR] Contenu du paquet v3.0 invalide.')
    for member in members:
        data=tar.extractfile(member).read()
        path=Path(sys.argv[2])/'final'/member.name
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(data)
        if path.suffix=='.py': compile(data.decode('utf-8'),str(path),'exec')
print('[OK] Moteur et interface complete v3.0 verifies.')
PY_UNPACK_V300

for script in "$WORK"/*.sh; do
  bash -n "$script" || { echo "[ERREUR] Script invalide : $script" >&2; exit 1; }
done

# Sur une installation v2.3.1 deja fonctionnelle, conserver tous les prerequis.
# Le paquet reste COMPLET et peut installer de zero quand il n'y a aucun moteur.
CURRENT_MEDIA=0
if [[ -f "$BASE/app.py" && ! -L "$BASE/app.py" && -f "$BASE/media_v23.py" && -f "$WEB/mobile_web.py" && -f "$WEB/app.js" && -f "$WEB/index.html" ]]; then
  if grep -Fq '# BLONDIN-V23-MEDIAZIP' "$BASE/app.py" && \
     { grep -Fq "'version': 'v2.3.1-TEST'" "$BASE/app.py" || grep -Fq "'version': 'v2.3.2-TEST'" "$BASE/app.py" || grep -Fq "'version': 'v2.3.3-TEST'" "$BASE/app.py" || grep -Fq "'version': 'v2.3.4-TEST'" "$BASE/app.py" || grep -Fq "'version': 'v3.0'" "$BASE/app.py"; }; then
    CURRENT_MEDIA=1
  fi
fi
if [[ "$CURRENT_MEDIA" == 1 ]]; then
  echo '[ETAPE BASE] Version existante reconnue : donnees et services conserves.'
else
# La base est deja valide si elle porte une des empreintes officielles de ce pack.
# Le marqueur exact preserve la v2.2 deja corrigee pendant une reinstallation.
PATCHED_MANUAL=0
if [[ -f "$BASE/app.py" && -f "$WEB/app.js" ]] && grep -Fq 'BLONDIN-V22-MANUAL-CHECK' "$BASE/app.py" && grep -Fq 'BLONDIN-V22-MANUAL-CHECK' "$WEB/app.js"; then
  PATCHED_MANUAL=1
fi
NEED_BASE=1
if [[ "$PATCHED_MANUAL" == 1 ]]; then NEED_BASE=0; fi
if [[ "$PATCHED_MANUAL" == 0 && -f "$BASE/app.py" && -f "$BASE/dossiers.json" && -f "$PORT" ]]; then
  if python3 - "$BASE/app.py" <<'PY_BASE'
import hashlib,sys
sha=hashlib.sha256(open(sys.argv[1],'rb').read()).hexdigest()
valid={'1e8d1e623aa9874c4cfedbf72cee51bc6958846b741b0ac1b3d7f327f85d3777', 'fe64cbf1b414edf5598bd8cbdc939e0c11204fd66003a1ae0813efe99f60e542', '0408b0983c9ebd9cdbe0f678761f76dffaa4040e90ace270a2edd1346b07cdbc',
       '9dbc6f602d3412292b419cb187fa9d0f93459a519329909740bc19f0366f6ece', '2c5e1c844b56a62e67403e2752518041b2f7eb6ae300cc55b1fef60e903bb7a4', '64b85c56d78c039646c1148486fb59970d96fb9aa216bf2ecfdc278024a375a5'}
sys.exit(0 if sha in valid else 1)
PY_BASE
  then NEED_BASE=0;fi
fi

echo ''
echo '============================================================'
echo '  SAUVEGARDE 1FICHIER ★ BLONDIN EDITION ★'
echo '  1FICHIER-BLONDIN-V3.4.4 COMPLETE / BATOCERA 44 + MOBILE'
echo '============================================================'
if [[ "$NEED_BASE" == 1 ]]; then
  echo '[ETAPE 1/7] Installation / validation du moteur Batocera.'
  bash "$WORK/01-moteur.sh"
else
  echo '[ETAPE 1/7] Moteur v2.0.2 reconnu deja present : conserve.'
fi
if [[ "$SHUTDOWN_V3_PRESENT" == 0 ]]; then
  echo '[ETAPE 2/7] Extinction automatique absente : garde non requise, fichiers externes intacts.'
elif ! grep -Fq '1FICHIER-BLONDIN-GUARD-V1' "$TRIGGER"; then
  echo '[ETAPE 2/7] Installation de la protection extinction.'
  bash "$WORK/02-garde-extinction.sh"
else
  echo '[ETAPE 2/7] Protection extinction deja installee : conservee.'
fi
NEED_MOBILE=1
if [[ -f "$WEB/mobile_web.py" && -f "$WEB/app.js" && -f "$WEB/index.html" && -f "$WEB/hold_gate.py" && -f "$WEB/auth.json" && -f "$SVC" ]]; then
  if grep -Fq 'BLONDIN-MOBILE-HOLD-V1' "$TRIGGER"; then
    NEED_MOBILE=0
  fi
fi
if [[ "$NEED_MOBILE" == 1 ]]; then
  echo '[ETAPE 3/7] Installation du module mobile et du mot de passe (si absent).'
  # Installer le module mobile meme sans Extinction V3, mais sans toucher aux hooks.
  if [[ "$SHUTDOWN_V3_PRESENT" == 0 ]]; then
    python3 - "$WORK/03-mobile.sh" <<'PY_OPTIONAL_SHUTDOWN'
from pathlib import Path
import sys
p=Path(sys.argv[1]); s=p.read_text(encoding='utf-8')
old="    if not TRIGGER.is_file():fail('Script d extinction V3 absent : installation refusee.')\n    raw_trigger=TRIGGER.read_bytes()"
new="    if not TRIGGER.is_file():\n        raw_trigger=b'1FICHIER-BLONDIN-GUARD-V1 BLONDIN-MOBILE-HOLD-V1'\n    else:\n        raw_trigger=TRIGGER.read_bytes()"
if s.count(old)!=1:raise SystemExit('[ERREUR] Adaptation mobile hors Extinction V3 incompatible.')
p.write_text(s.replace(old,new,1),encoding='utf-8')
print('[OK] Module mobile pret pour Batocera vierge (aucun script extinction cree).')
PY_OPTIONAL_SHUTDOWN
    bash -n "$WORK/03-mobile.sh"
  fi
  bash "$WORK/03-mobile.sh"
else
  echo '[ETAPE 3/7] Module mobile et mot de passe presents : conserves.'
fi

if [[ "$PATCHED_MANUAL" == 1 ]]; then
  echo '[ETAPES 4-7/8] v2.2 manuelle deja active : anciens correctifs conserves, aucun retour arriere.'
else
# Si R2 est deja installe, ne pas revenir a R1 : mise a jour idempotente.
if python3 - "$BASE/app.py" "$WEB/mobile_web.py" <<'PY_FINAL_VERSION'
import hashlib,sys
wanted=('1e8d1e623aa9874c4cfedbf72cee51bc6958846b741b0ac1b3d7f327f85d3777',
        '8b7de49da9d9576b5accc5b88234cf2d820dd512b2fbfa91f44c31551b334926')
sums=[hashlib.sha256(open(x,'rb').read()).hexdigest() for x in sys.argv[1:]]
sys.exit(0 if tuple(sums)==wanted or tuple(sums)==('2c5e1c844b56a62e67403e2752518041b2f7eb6ae300cc55b1fef60e903bb7a4', wanted[1]) or tuple(sums)==('64b85c56d78c039646c1148486fb59970d96fb9aa216bf2ecfdc278024a375a5','9909c4d1f48b1c983bf765f36e0d3fa318260e348f33bb07cb02c27d08f70715') or tuple(sums)==('64b85c56d78c039646c1148486fb59970d96fb9aa216bf2ecfdc278024a375a5','ef92a2aa65034f9d666e1ea1e2ca6624f1ef48870b3b2e49ca99ab463a8affba') else 1)
PY_FINAL_VERSION
then
  echo '[ETAPE 4/7] Correctifs R1 deja presents dans R2 : aucun retour arriere.'
else
  echo '[ETAPE 4/7] Application des corrections communes R1 + M1.2.'
  if ! lock_available; then
    echo '[ERREUR] Un processus a repris le verrou entre les etapes.' >&2
    echo '[INFO] Ne pas supprimer transfert.lock ; verifier les processus Rclone et EmulationStation.' >&2
    exit 1
  fi
  bash "$WORK/04-correctifs-R1-M1.2.sh"
fi
echo '[ETAPE 5/7] Gestion unique compte 1fichier depuis Batocera et Mobile.'
if python3 - "$BASE/app.py" "$WEB/mobile_web.py" <<'PY_UPTODATE_21'
import hashlib,sys
s=[hashlib.sha256(open(x,'rb').read()).hexdigest() for x in sys.argv[1:]]
sys.exit(0 if s in (['64b85c56d78c039646c1148486fb59970d96fb9aa216bf2ecfdc278024a375a5','9909c4d1f48b1c983bf765f36e0d3fa318260e348f33bb07cb02c27d08f70715'],
       ['64b85c56d78c039646c1148486fb59970d96fb9aa216bf2ecfdc278024a375a5','ef92a2aa65034f9d666e1ea1e2ca6624f1ef48870b3b2e49ca99ab463a8affba']) else 1)
PY_UPTODATE_21
then
  echo '[ETAPE 5/7] Gestion du compte deja presente dans v2.1 : conservee.'
else
  bash "$WORK/05-compte-R2-M1.3.sh"
fi

echo '[ETAPE 6/7] Journaux automatiques v2.1.'
# La migration v2.1 refuse les sources v2.2 (version posterieure) : la sauter.
if python3 - "$WEB/mobile_web.py" <<'PY_WEB_V22'
import hashlib,sys
print('') if False else None
sys.exit(0 if hashlib.sha256(open(sys.argv[1],'rb').read()).hexdigest()=='ef92a2aa65034f9d666e1ea1e2ca6624f1ef48870b3b2e49ca99ab463a8affba' else 1)
PY_WEB_V22
then
  echo '[ETAPE 6/7] Journaux v2.1 deja installes, conserves.'
else
  bash "$WORK/06-journaux-v2.1.sh"
fi

echo '[ETAPE 7/7] Evolutions mobiles v2.2.'
bash "$WORK/07-web-v2.2.sh"
fi

echo '[ETAPE 8/8] Verification manuelle, sans controle automatique apres copie.'
bash "$WORK/08-verification-manuelle-v2.2.sh"

fi  # fin de l installation complete des prerequis lorsque necessaire

echo '[ETAPE FINALE] Installation des moteurs et interfaces v3.0.'
python3 - "$BASE" "$WORK/final" <<'PY_INSTALL_V300'
import hashlib,os,shutil,sys,tempfile,time
from pathlib import Path
base=Path(sys.argv[1]);payload=Path(sys.argv[2]);backup_dir=base/'backups'
paths={'app.py':'app.py', 'media_v23.py':'media_v23.py',
       'mobile/mobile_web.py':'mobile/mobile_web.py',
       'mobile/app.js':'mobile/app.js', 'mobile/index.html':'mobile/index.html'}
for rel in paths:
    dst=base/rel
    if not dst.parent.is_dir() or dst.is_symlink():
        raise SystemExit('[ERREUR] Chemin inattendu pour : '+rel)
    if rel!='media_v23.py' and not dst.is_file():
        raise SystemExit('[ERREUR] Composant attendu absent : '+rel)
if backup_dir.is_symlink():
    raise SystemExit('[ERREUR] Dossier de sauvegarde invalide.')
source={rel:(payload/rel).read_bytes() for rel in paths}
for rel,data in source.items():
    if rel.endswith('.py'):
        compile(data.decode('utf-8'),rel,'exec')
changed=[rel for rel in paths if not (base/rel).is_file() or (base/rel).read_bytes()!=source[rel]]
if not changed:
    print('[OK] Installation v3.0 deja complete : aucun fichier remplace.')
    sys.exit(0)
backup=backup_dir/('avant-installation-complete-v3.0-'+time.strftime('%Y%m%d-%H%M%S')+'-'+str(os.getpid()))
backup.mkdir(parents=True,exist_ok=False)
for rel in changed:
    original=base/rel
    if original.is_file():
        target=backup/rel;target.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(original,target)
installed=[]
try:
    for rel in changed:
        target=base/rel
        fd,temp=tempfile.mkstemp(prefix='.'+target.name+'.v300-',dir=str(target.parent))
        try:
            with os.fdopen(fd,'wb') as handle:
                handle.write(source[rel]);handle.flush();os.fsync(handle.fileno())
            os.chmod(temp, (target.stat().st_mode&0o777) if target.exists() else 0o600)
            os.replace(temp,target)
        finally:
            Path(temp).unlink(missing_ok=True)
        installed.append(rel)
    for rel in changed:
        if (base/rel).read_bytes()!=source[rel]:
            raise RuntimeError('Validation apres installation echouee : '+rel)
except Exception:
    for rel in reversed(installed):
        previous=backup/rel
        if previous.is_file():
            shutil.copy2(previous,base/rel)
        else:
            (base/rel).unlink(missing_ok=True)
    raise
print('[OK] Installation complete v3.0 : '+str(len(changed))+' composant(s) actualise(s).')
print('[OK] Exclusions, envoi protege et renvoi de media.zip, etapes visuelles et mobile.')
print('[OK] Configurations, Rclone, historique, ntfy et ZIP locaux conserves si besoin.')
print('[INFO] Copie de securite : '+str(backup))

PY_INSTALL_V300

echo '[ETAPE WEB v3.1] Interface compacte, historique par systeme et dernier transfert.'
python3 - "$BASE" <<'PY_WEB_V31'
#!/usr/bin/env python3
# BLONDIN-WEB-V31-NAV : onglets et historique des sauvegardes pour Batocera 44.
import os,sys,shutil,tempfile,time
from pathlib import Path

MARKER='BLONDIN-WEB-V31-NAV'
CSS=r"""
/* BLONDIN-WEB-V31-NAV */
.b31-nav{position:sticky;top:0;z-index:8;padding:11px 12px;margin:0 0 12px;background:#121f33;border:1px solid #435a78;border-radius:12px;box-shadow:0 5px 18px #02081777}
.b31-nav label{font-size:.8rem;font-weight:600;color:#afc5e4;display:block;margin-bottom:5px}
.b31-nav select{width:100%;max-width:100%;padding:12px;font-size:1rem;background:#192c45;color:#f2f6ff;border:1px solid #6a89b0;border-radius:9px}
.b31-page[hidden],.b31-mini[hidden]{display:none!important}
.b31-mini{margin-top:9px;padding:8px 10px;border-radius:8px;background:#354466;color:#fff;cursor:pointer;border:1px solid #597499;width:100%;text-align:left}
.b31-recent-card{border:1px solid #3a5271;border-radius:12px;padding:12px;margin:10px 0;background:#142237}
.b31-recent-card h3{margin:0 0 8px;font-size:1.05rem}
.b31-recent-row{display:flex;gap:10px;align-items:center;border-bottom:1px solid #32435b;padding:10px 0;min-width:0}
.b31-recent-row:last-child{border-bottom:0}
.b31-indicator{width:1.35rem;text-align:center;font-size:1.35rem;flex:none}
.b31-ok{color:#64d9a9}.b31-pending{color:#f6cd76}.b31-error{color:#fa9292}
.b31-name{font-weight:700;overflow-wrap:anywhere}
.b31-small{font-size:.85rem;color:#afbdd2;overflow-wrap:anywhere}
.b31-flex{flex:1;min-width:0}
.b31-inline{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.b31-input{width:100%;padding:11px;border-radius:8px;border:1px solid #607d9f;background:#112035;color:white}
.b31-details{margin:12px 0}.b31-details summary{cursor:pointer;font-weight:700;padding:10px;border-radius:9px;background:#203451}
.b31-details>.panel{margin:9px 0 0}
.b31-muted{font-size:.85rem;color:#b6c4d5}
.b31-verify-list{display:grid;gap:8px;margin:12px 0}
.b31-verify-list label{display:flex;align-items:center;gap:8px;padding:10px;background:#16263c;border-radius:8px}
.b31-verify-list input{width:18px;height:18px;flex:none}
"""
JS=r"""
// BLONDIN-WEB-V31-NAV — 6 rubriques sans changer les appels existants.
(function(){
'use strict';
const pages=[['home','🏠 Accueil'],['save','💾 Sauvegarder'],['history','📅 Historique'],['verify','✅ Vérification'],['account','☁️ Compte 1fichier / Rclone'],['tools','⚙️ Réglages et outils']];
const dash=document.getElementById('dashboard');
if(!dash||dash.dataset.b31Ready==='yes')return;
const d=id=>document.getElementById(id);
const panels=[...dash.children].filter(e=>e.matches('section.panel'));
const systemPanel=panels.find(p=>p.contains(d('state')));
const savePanel=panels.find(p=>p.contains(d('folders')));
const operationsPanel=panels.find(p=>p.contains(d('history')));
const logPanel=panels.find(p=>p.contains(d('log')));
if(!systemPanel||!savePanel||!operationsPanel||!logPanel||!d('accountPanel')||!d('maintenancePanel')||!d('checkBtn'))return;
const el=(tag,cls,value)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(value!==undefined)e.textContent=String(value);return e;};
const nav=el('div','b31-nav'),lab=el('label',null,'MENU PRINCIPAL'),menu=el('select');
lab.htmlFor='b31-menu';menu.id='b31-menu';menu.setAttribute('aria-label','Choisir une rubrique');
for(const [key,label] of pages){const o=el('option',null,label);o.value=key;menu.append(o);}
const mini=el('button','b31-mini');mini.type='button';mini.hidden=true;nav.append(lab,menu,mini);
const views={};
for(const [key] of pages){const v=el('section','b31-page');v.id='b31-page-'+key;v.hidden=key!=='home';views[key]=v;}
dash.prepend(nav);
for(const [key] of pages)dash.append(views[key]);
const homePanel=el('section','panel');homePanel.append(el('h2',null,'Tableau de bord'));
const lastBox=el('div','b31-recent-card');lastBox.append(el('h3',null,'Dernière sauvegarde terminée'));
const lastValue=el('div','b31-small','Aucune sauvegarde enregistrée.');lastValue.id='b31-last-save';lastBox.append(lastValue);
const recentHeading=el('div','b31-inline');recentHeading.append(el('h3',null,'Sauvegardés récemment'));
const goAll=el('button','small ghost','Voir tout');goAll.type='button';recentHeading.append(goAll);
const recentList=el('div');recentList.id='b31-recent-home';
homePanel.append(lastBox,recentHeading,recentList,el('p','b31-muted','✓ Vérifié et validé · ◷ Transféré, non vérifié · ✗ Transfert ou contrôle en erreur'));
views.home.append(homePanel,systemPanel);
views.save.append(savePanel,d('categoryPanel'),d('mediaRetryPanel'));
const historyTop=el('section','panel');historyTop.append(el('h2',null,'Sauvegardes récentes'));
const search=el('input','b31-input');search.type='search';search.placeholder='Rechercher un système…';search.id='b31-search';search.setAttribute('aria-label','Rechercher un système');
const fullList=el('div');historyTop.append(search,fullList);views.history.append(historyTop);
const detail=el('details','b31-details');detail.append(el('summary',null,'Afficher toutes les opérations (journaux détaillés)'),operationsPanel);views.history.append(detail);
const verifyPanel=el('section','panel');verifyPanel.append(el('h2',null,'Vérification manuelle'));
verifyPanel.append(el('p','b31-muted','Contrôle des noms et des tailles, sans retransfert. Sélectionne les systèmes à contrôler.'));
const verifyList=el('div','b31-verify-list');verifyPanel.append(verifyList);
verifyPanel.append(d('checkBtn'));views.verify.append(verifyPanel);
views.account.append(d('accountPanel'));
const toolsIntro=el('section','panel');toolsIntro.append(el('h2',null,'Outils et extinction'));
const powerGroup=d('powerOffBtn').closest('.actions');if(powerGroup)toolsIntro.append(powerGroup);
toolsIntro.append(el('p','b31-muted','Extinction manuelle avec confirmation, indisponible pendant une opération.'));
views.tools.append(toolsIntro,d('maintenancePanel'),logPanel,d('logoutBtn'));
const show=key=>{if(!views[key])key='home';for(const [id,v] of Object.entries(views))v.hidden=id!==key;menu.value=key;nav.dataset.active=key;};
menu.addEventListener('change',()=>show(menu.value));goAll.addEventListener('click',()=>show('history'));
mini.addEventListener('click',()=>show('home'));
const when=v=>{const m=/^(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d)/.exec(String(v||''));return m?m[3]+'/'+m[2]+'/'+m[1]+' · '+m[4]+':'+m[5]:String(v||'Date inconnue');};
const latestCopies=s=>{
 const rows=Array.isArray(s.history)?[...s.history]:[];
 rows.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 const byId=new Map();
 for(const x of rows){if(x.mode!=='copy')continue;
  const id=String(x.id||x.nom||'');if(!id||byId.has(id))continue;
  const check=rows.find(c=>c.mode==='check'&&c.etat!=='annule'&&String(c.id||c.nom||'')===id&&String(c.date||'')>=String(x.date||''));
  const state=!x.ok?'error':check?(check.ok&&!(Number(check.ecarts)||0)?'ok':'error'):
   x.controle==='non_effectue'||!x.controle?'pending':(x.controle==='valide'?'ok':'pending');
  byId.set(id,{name:String(x.nom||id),date:x.date||'',state});
 }
 return [...byId.values()];
};
const stateMeta={ok:['✓','Vérifiée et validée','b31-ok'],pending:['◷','Transférée · non vérifiée','b31-pending'],error:['✗','Échec du transfert ou du contrôle','b31-error']};
function line(item){const [glyph,desc,color]=stateMeta[item.state]||stateMeta.pending;
 const row=el('div','b31-recent-row');row.append(el('span','b31-indicator '+color,glyph));
 const body=el('div','b31-flex');body.append(el('div','b31-name',item.name));body.append(el('div','b31-small',when(item.date)+' · '+desc));row.append(body);return row;
}
let recent=[];
function renderFull(){const q=search.value.trim().toLocaleLowerCase('fr-FR');fullList.replaceChildren();let count=0;
 for(const item of recent){if(q&&!item.name.toLocaleLowerCase('fr-FR').includes(q))continue;fullList.append(line(item));count++;}
 if(!count)fullList.append(el('p','b31-muted',q?'Aucun système trouvé.':'Aucune sauvegarde récente.'));
}
search.addEventListener('input',renderFull);
let oldNames='';
function updateV31(s){
 recent=latestCopies(s);lastValue.replaceChildren();
 if(recent.length)lastValue.append(line(recent[0]));else lastValue.textContent='Aucune sauvegarde enregistrée.';
 recentList.replaceChildren();for(const item of recent.slice(0,5))recentList.append(line(item));
 if(!recent.length)recentList.append(el('p','b31-muted','Aucune sauvegarde récente.'));
 renderFull();
 mini.hidden=!s.active;
 if(s.active){const op=s.operation||{},prog=s.progress||{};
  mini.textContent='◷ '+(op.mode==='check'?'Vérification':op.mode==='media_retry'?'Renvoi media.zip':'Sauvegarde')+' : '+String(prog.dossier||(op.dossiers||[]).join(', ')||'Voir la progression');
 }
 const entries=Array.isArray(s.entries)?s.entries:[];
 const signature=entries.map(x=>x.id+'|'+x.nom).join('\n');
 if(signature!==oldNames){oldNames=signature;verifyList.replaceChildren();
  for(const x of entries){const label=el('label'),cb=el('input');cb.type='checkbox';cb.dataset.verifyId=x.id;
   cb.addEventListener('change',()=>{if(cb.checked)selected.add(x.id);else selected.delete(x.id);
    const original=[...d('folders').querySelectorAll('input[type=checkbox]')].find(c=>c.dataset.focusid===x.id);
    if(original)original.checked=cb.checked;updateSelectedUI();
   });
   label.append(cb,el('span',null,x.nom));verifyList.append(label);
  }
 }
 for(const cb of verifyList.querySelectorAll('input[type=checkbox]')){cb.checked=selected.has(cb.dataset.verifyId);cb.disabled=!!s.active;}
}
const oldRender=render;
render=function(s){oldRender(s);updateV31(s);};
dash.dataset.b31Ready='yes';show('home');
})();
"""
def atomic_write(path,data):
    mode=path.stat().st_mode & 0o777
    fd,tmp=tempfile.mkstemp(dir=str(path.parent),prefix='.'+path.name+'.v31-')
    try:
        with os.fdopen(fd,'w',encoding='utf-8',newline='\n') as out:
            out.write(data);out.flush();os.fsync(out.fileno())
        os.chmod(tmp,mode);os.replace(tmp,path)
    finally:
        Path(tmp).unlink(missing_ok=True)
def main():
    if len(sys.argv)!=2:raise SystemExit('[ERREUR] Chemin du moteur absent.')
    base=Path(sys.argv[1]);web=base/'mobile'
    paths=[web/'index.html',web/'app.js',web/'mobile_web.py']
    if any(not p.is_file() or p.is_symlink() for p in paths) or web.is_symlink():
        raise SystemExit('[ERREUR] Interface Web absente ou chemin invalide.')
    html,js,backend=[p.read_text(encoding='utf-8') for p in paths]
    if all(MARKER in s for s in (html,js,backend)):
        print('[OK] Interface v3.1 deja installee.');return
    if any(MARKER in s for s in (html,js,backend)):
        raise SystemExit('[ERREUR] Mise a jour Web partielle detectee : rien ne sera modifie.')
    old_history='history = app.load_history()[-15:]'
    old_fields="('nom','date','mode','ok','etat','copies','erreurs','ecarts','reverification','controle','media')"
    if any(x not in html for x in ('id="dashboard"','id="history"','id="accountPanel"','id="checkBtn"','id="folders"')) or any(x not in js for x in ('function render(s)',"'/api/status'",'function updateSelectedUI()')) or old_history not in backend or old_fields not in backend or '</head>' not in html:
        raise SystemExit('[ERREUR] Composants Web v3.0 non reconnus : aucune modification.')
    new_html=html.replace('</head>','<style>\n'+CSS+'\n</style></head>',1).replace('· v3.0','· v3.1',1)
    new_js=js.rstrip()+'\n'+JS+'\n'
    new_backend=(backend.replace(old_history,'history = app.load_history()[-300:]',1)
        .replace(old_fields,"('id','job','nom','date','mode','ok','etat','copies','erreurs','ecarts','reverification','controle','media')",1)
        .replace("'port':PORT, 'version':'v3.0'","'port':PORT, 'version':'v3.1'",1)
        +'\n# BLONDIN-WEB-V31-NAV : historique complet accessible au tableau de bord.\n')
    if any(txt.count(MARKER)!=1 for txt in (new_html,new_js,new_backend)):
        raise SystemExit('[ERREUR] Validation du patch impossible.')
    compile(new_backend,'mobile_web.py','exec')
    folder=base/'backups'
    if folder.is_symlink():raise SystemExit('[ERREUR] Dossier de secours invalide.')
    backup=folder/('avant-web-v3.1-'+time.strftime('%Y%m%d-%H%M%S')+'-'+str(os.getpid()))
    backup.mkdir(parents=True,exist_ok=False)
    for p in paths:shutil.copy2(p,backup/p.name)
    changed=[]
    try:
        for p,value in zip(paths,(new_html,new_js,new_backend)):
            atomic_write(p,value);changed.append(p)
        if any(MARKER not in p.read_text(encoding='utf-8') for p in paths):
            raise RuntimeError('Controle apres installation echoue.')
    except Exception:
        for p in changed:shutil.copy2(backup/p.name,p)
        raise
    print('[OK] Web v3.1 : accueil, 6 rubriques, dates, verification, historique et noms.')
    print('[INFO] Anciens fichiers Web conserves dans : '+str(backup))
if __name__=='__main__': main()

PY_WEB_V31

