# BLONDIN-V31-CATEGORY-SUBMENUS-INSTALL ; installation locale, sans action Rclone.
import os, shutil, sys, tempfile, time
from pathlib import Path
p=Path(sys.argv[1])/'app.py'
if not p.is_file() or p.is_symlink():
    raise SystemExit('[ERREUR] Moteur app.py manquant ou chemin non sûr.')
old=p.read_text(encoding='utf-8')
if 'BLONDIN-V31-CATEGORIES-B' not in old:
    raise SystemExit('[ERREUR] Moteur catégories v3.1 non reconnu.')
if 'BLONDIN-V31-CATEGORY-SUBMENUS' in old:
    print('[OK] Sous-menus déjà installés.')
    raise SystemExit(0)
def replace_section(s, begin, end, code):
    if s.count(begin)!=1 or s.count(end)!=1 or s.index(begin)>=s.index(end):
        raise RuntimeError('Structure du moteur inattendue : installation refusée.')
    a=s.index(begin)
    b=s.index(end,a)
    return s[:a]+code+'\n'+s[b:]
updated=replace_section(old,'def select_entry(data):\n','\ndef add_entry():\n',"def select_entry(data):\n    \"\"\"Catégorie puis système ; états/dates issus des bilans locaux, sans requête réseau.\"\"\"\n    if not data:\n        print('\\nAucun dossier configuré.')\n        return None\n    statuses = backup_list_states(data)\n    mapping = category_mapping()\n    footer = [\n        paint('  LÉGENDE — ', '1;36') +\n        paint('✔', '1;32') + ' contrôle jeux OK   ' +\n        paint('!', '1;33') + ' non vérifié   ' +\n        paint('✖', '1;31') + ' erreur',\n        '            ' + paint('–', '0;33') + ' annulé   ' +\n        paint('·', '0;37') + ' aucun bilan   |   Date : dernière sauvegarde',\n    ]\n    while True:\n        groupes = {cat: [] for cat in CATEGORIES}\n        for entry in data:\n            groupes[category_of(entry, mapping)].append(entry)\n        category_options = [\n            (str(i), '{}  ({} systèmes)'.format(cat, len(groupes[cat])))\n            for i, cat in enumerate(CATEGORIES, 1)\n        ]\n        category_options.append(('0', 'Retour au menu précédent'))\n        choice = NAV.choose(category_options, 'CHOISIR UNE CATEGORIE')\n        if choice in (None, '0'):\n            return None\n        category = CATEGORIES[int(choice) - 1]\n        selected_entries = groupes[category]\n        if not selected_entries:\n            print('  Aucun système dans la catégorie {}.'.format(category))\n            pause()\n            continue\n        options = [('1', 'Retour aux catégories')]\n        for i, entry in enumerate(selected_entries, 2):\n            state, date = statuses[entry['id']]\n            name = ('[{}] {}'.format(category, entry['nom'])).replace('\\r', ' ').replace('\\n', ' ')[:31]\n            options.append((str(i), '{} {:<31}  {}'.format(backup_symbol(state), name, date)))\n        picked = NAV.choose(options, 'CATEGORIE : ' + category.upper(), footer=footer)\n        if picked in (None, '1'):\n            continue\n        index = int(picked) - 2\n        if 0 <= index < len(selected_entries):\n            return selected_entries[index]\n")
updated=replace_section(updated,'def menu_categories_v31():\n','\ndef category_before_backup(x):\n',"def menu_categories_v31():\n    \"\"\"Reclasser sans déplacer d'archive, dans une navigation par catégories.\"\"\"\n    while True:\n        x = select_entry(entries())\n        if x is None:\n            return\n        old = category_of(x)\n        options = [(str(i), c + (' (actuel)' if c == old else ''))\n                   for i, c in enumerate(CATEGORIES, 1)] + [('0', 'Annuler')]\n        answer = NAV.choose(options, 'CATEGORIE : ' + x['nom'][:34])\n        if answer in (None, '0'):\n            continue\n        new = CATEGORIES[int(answer) - 1]\n        if new == old:\n            print('  Ce système appartient déjà à cette catégorie.')\n            pause()\n            continue\n        print('\\n  {} : {} -> {}'.format(x['nom'], old, new))\n        print('  Aucune archive 1fichier ne sera déplacée ou renvoyée.')\n        if NAV.confirm('Confirmer ce reclassement local ?'):\n            category_assign({str(x['id']): new}, confirm=True)\n            print('  Classement enregistré.')\n        pause()\n")
updated=updated.replace('def select_entry(data):','# BLONDIN-V31-CATEGORY-SUBMENUS\ndef select_entry(data):',1)
compile(updated,str(p),'exec')
backup_dir=p.parent/'backups'
if backup_dir.is_symlink():
    raise RuntimeError('Dossier de sauvegarde invalide.')
backup_dir.mkdir(parents=True,exist_ok=True)
backup=backup_dir/('avant-menu-categories-v3.1-'+time.strftime('%Y%m%d-%H%M%S')+'-'+str(os.getpid())+'.py')
shutil.copy2(p,backup)
fd,tmp=tempfile.mkstemp(prefix='.app-menu-v31-',dir=str(p.parent))
try:
    with os.fdopen(fd,'w',encoding='utf-8',newline='\n') as f:
        f.write(updated)
        f.flush()
        os.fsync(f.fileno())
    os.chmod(tmp,p.stat().st_mode&0o777)
    os.replace(tmp,p)
    if 'BLONDIN-V31-CATEGORY-SUBMENUS' not in p.read_text(encoding='utf-8'):
        raise RuntimeError('Contrôle final du sous-menu échoué.')
except Exception:
