stage=stage.replace("a=once(a,needle_worker,replacement_worker)\na+='\\n# '+MARK+' - moteur\\n'","a=once(a,needle_worker,replacement_worker)\na=once(a, \"rec = {'id': x['id'], 'nom': x['nom'], 'source': x['source'],\", \"rec = {'job': job, 'id': x['id'], 'nom': x['nom'], 'source': x['source'],\")\na+='\\n# '+MARK+' - moteur\\n'",1)
