cat >"$WORK/install-v3.4.sh" <<'__BLONDIN_V344_SOURCE_V34__'
#!/usr/bin/env bash
# Sauvegarde 1fichier ★ BLONDIN EDITION ★ v3.4 — mise a jour Web AUTONOME hors ligne
# Batocera 44. Necessite une installation v3.3 deja presente.
# --extract /chemin/fichier.py : extrait le correctif sans l'installer.
set -Eeuo pipefail
command -v python3 >/dev/null || { echo '[ERREUR] Python3 manquant.' >&2; exit 1; }
MODE=install
WORK=''
if [[ "${1:-}" == '--extract' ]]; then
  [[ -n "${2:-}" ]] || { echo '[ERREUR] Chemin d extraction manquant.' >&2; exit 1; }
  MODE=extract
  OUT="$2"
else
  [[ "$(id -u)" -eq 0 ]] || { echo '[ERREUR] Executer comme root.' >&2; exit 1; }
  WORK=$(mktemp -d /tmp/blondin-web-v34.XXXXXXXX)
  OUT="$WORK/web-v3.4-patch.py"
  trap 'rm -rf -- "$WORK"' EXIT
fi
python3 - "$OUT" <<'PY_EXTRACT_V34'
