compressed=base64.b64decode(''.join(payload.split()),validate=True)
data=gzip.decompress(compressed)
if hashlib.sha256(data).hexdigest()!='b94ac5fd2f0534deb543f2e841ec3377f75d047ce788d56af1a1080e785f7d11':
    raise SystemExit('[ERREUR] Correctif v3.4 invalide : empreinte SHA256 differente.')
p=Path(sys.argv[1]);p.write_bytes(data);p.chmod(0o700)
print('[OK] Correctif Web v3.4 extrait et verifie.')
