  if command -v batocera-services >/dev/null 2>&1; then
    batocera-services enable Sauvegarde1fichierMobile || echo '[ATTENTION] Activation service au demarrage non confirmee.' >&2
  fi
  bash "$SVC" start || echo '[ATTENTION] Demarrer le service Web manuellement.' >&2
  WEB_STOPPED_FOR_UPGRADE=0
fi

# Securite avant le reboot : la session graphique presente au depart doit etre encore active.
if [[ -z "${BLONDIN_TEST_ROOT:-}" && "$WAS_ES_RUNNING" == 1 ]]; then
  if ! pgrep -x labwc >/dev/null 2>&1; then
    echo '[ATTENTION] Compositeur graphique absent avant le reboot. Tentative de restauration.' >&2
    start_es_clean_outer || {
      echo '[ERREUR] Graphique non restaure : annulation du reboot.' >&2
      exit 1
    }
  fi
fi

echo ''
echo '[OK] Installation COMPLETE autonome terminee.'
echo '[OK] v3.4.4 : sauvegarde, media.zip, inventaire cloud, categories et Web mobile ameliore.'
echo '[OK] Configuration des dossiers, mot de passe et ntfy preserves si existants.'
echo '[INFO] Adresse : http://IP_DE_BATOCERA:8765 (HTTP, pas HTTPS)'
echo '[INFO] A distance : utiliser le VPN WireGuard de la Freebox.'
echo '[SECURITE] Ne pas ouvrir le port 8765 vers Internet.'
if ! command -v rclone >/dev/null 2>&1 || [[ ! -f "$SYSROOT/system/.config/rclone/rclone.conf" ]]; then
  echo '[INFO] Compte non configure : le configurer depuis le menu Compte 1fichier ou le telephone.'
fi
# Redemarrer Batocera seulement lorsque toutes les etapes se sont achevees sans erreur.
# Aucun reboot n'est declenche dans le mode simulation BLONDIN_TEST_ROOT.
if [[ -z "${BLONDIN_TEST_ROOT:-}" ]]; then
  echo '[OK] Toutes les etapes sont terminees. Redemarrage complet de Batocera.'
  echo '[INFO] La connexion SSH va se couper. Reconnectez-vous une fois Batocera demarre.'
  sync
  # Le nettoyage des fichiers temporaires est effectue avant le redemarrage.
  trap - EXIT
  cleanup
  if ! reboot; then
    echo '[ERREUR] La mise a jour est installee, mais le redemarrage a echoue.' >&2
    echo '[ACTION] Redemarrer manuellement Batocera.' >&2
    exit 1
  fi
else
  echo '[TEST] Redemarrage complet desactive en environnement de simulation.'
fi
exit 0

